// DOPISZ NA KOŃCU PRE-REQUEST WYBORU PŁATNOŚCI.
(function () {
    let selected;
    try { selected = JSON.parse(pm.collectionVariables.get("selectedPaymentMethod") || "null"); } catch (_) {}
    const code = pm.collectionVariables.get("selectedPaymentMethodCode");
    const token = pm.collectionVariables.get("tokenValue");
    if (!selected || !code || !token || selected.tokenValue !== token || selected.code !== code) {
        console.error("Brak aktualnego wyboru płatności. Uruchom najpierw GET płatności dla tego koszyka.");
        pm.execution.setNextRequest(null);
        pm.execution.skipRequest();
        return;
    }
    pm.variables.set("selectedPaymentMethodCode", code);
    let checkoutReport;
    try { checkoutReport = JSON.parse(pm.collectionVariables.get("checkoutReport") || "{}"); } catch (_) { checkoutReport = {}; }
    if (!checkoutReport || typeof checkoutReport !== "object" || Array.isArray(checkoutReport)) checkoutReport = {};
    checkoutReport.paymentMethodCode = code;
    checkoutReport.paymentMethodName = selected.name;
    pm.collectionVariables.set("checkoutReport", JSON.stringify(checkoutReport));
})();

pm.test("Status odpowiedzi jest 2xx", function () {
    pm.expect(pm.response.code).to.be.within(200, 299);
});

pm.test("Odpowiedź nie jest stroną HTML", function () {
    const contentType = (pm.response.headers.get("Content-Type") || "").toLowerCase();
    pm.expect(contentType).to.not.include("text/html");
});
